constraints:
1 ≤ N ≤ 10^{7}
0 ≤ A[i] ≤ 10^{9}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def maxIndexDiff(self, A, N):
		left = [0] * N
		right = [0] * N
		diff = 0
		(mini, maxi) = (A[0], A[N - 1])
		for i in range(N - 1, -1, -1):
			if A[i] >= maxi:
				maxi = A[i]
			right[i] = maxi
		(i, j) = (0, 0)
		while i < N and j < N:
			if A[i] <= right[j]:
				diff = max(diff, j - i)
				j += 1
			else:
				i += 1
		return diff
